// The model-facing posture context (UX spec section 4, ruling L18). One pure
// function builds it for the hosted adapter and, through the vendor copy, for
// the mod. The only import is a type, which the vendor script rewrites to the
// vendored contract file.

import type { ContextResult } from '../core/contract/types.ts';

export type PostureInput = Pick<ContextResult, 'banned' | 'requires_ask' | 'posture' | 'guardrails'>;

export interface PostureContextOptions {
  /**
   * The mod sets this. It removes a leading `[policy name] ` from each guardrail
   * and treats every item as untrusted text: control, escape, bidi and
   * zero-width characters go, any other character outside printable ASCII
   * becomes `?`, a newline becomes a space, and each item and each list is cut.
   * The hosted adapter leaves it unset, so its text stays as it was.
   */
  readonly forMod?: boolean;
}

const HEADER = '[LangGuard Arbiter — session context]';
const MAX_GUARDRAIL_LINES = 5;
export const MOD_MAX_NAME_CHARS = 128;
export const MOD_MAX_GUARDRAIL_CHARS = 300;
export const MOD_MAX_LIST_ENTRIES = 200;

// eslint-disable-next-line no-control-regex -- ESC and BEL are the bytes this sanitizer exists to strip
const ANSI = /\u001b(?:\[[0-?]*[ -/]*[@-~]|\][^\u0007\u001b]*(?:\u0007|\u001b\\)?|[@-Z\\-_])/g;
const SPACING = /[\r\n\t]+/g;
// eslint-disable-next-line no-control-regex -- the control range is what this sanitizer exists to strip
const INVISIBLE = /[\u0000-\u001f\u007f-\u009f\u200b-\u200f\u202a-\u202e\u2066-\u2069\ufeff]/g;
const NOT_PRINTABLE_ASCII = /[^ -~]/gu;
const POLICY_PREFIX = /^\[[^\]]*\](?: |$)/;

const clean = (text: string): string => text.replace(ANSI, '').replace(SPACING, ' ').replace(INVISIBLE, '').replace(NOT_PRINTABLE_ASCII, '?');

const cut = (text: string, limit: number): string => (text.length > limit ? `${text.slice(0, limit - 3)}...` : text);

const sanitize = (text: string, limit: number): string => cut(clean(text), limit);

// The prefix is stripped from the cleaned text: cleaning turns a tab or a newline into the space that the prefix ends with and removes a leading invisible character.
const description = (guardrail: string): string => cut(clean(guardrail).trim().replace(POLICY_PREFIX, '').trim(), MOD_MAX_GUARDRAIL_CHARS);

function listOf(items: readonly string[], separator: string, limit: number, forMod: boolean): string {
  if (!forMod) return items.join(separator);
  const shown = items.slice(0, MOD_MAX_LIST_ENTRIES).map((item) => sanitize(item, limit));
  const more = items.length - shown.length;
  return more > 0 ? `${shown.join(separator)}${separator}and ${more} more` : shown.join(separator);
}

export function buildPostureContext(context: PostureInput, options: PostureContextOptions = {}): string {
  const forMod = options.forMod === true;
  const lines: string[] = [HEADER];

  if (context.banned.length > 0) {
    lines.push(`BLOCKED tools (do NOT call): ${listOf(context.banned, ', ', MOD_MAX_NAME_CHARS, forMod)}`);
  }
  if (context.requires_ask.length > 0) {
    lines.push(`ASK-required tools (human approval needed): ${listOf(context.requires_ask, ', ', MOD_MAX_NAME_CHARS, forMod)}`);
  }

  const { posture } = context;
  const postureItems: string[] = [];
  if (posture.enforce_not_approved) postureItems.push('enforce_not_approved=true');
  if (posture.compliance_regimes.length > 0) {
    postureItems.push(`compliance=${listOf(posture.compliance_regimes, ',', MOD_MAX_NAME_CHARS, forMod)}`);
  }
  postureItems.push(`scope_default_tier=${forMod ? sanitize(posture.scope_default_tier, MOD_MAX_NAME_CHARS) : posture.scope_default_tier}`);
  lines.push(`Posture: ${postureItems.join('; ')}`);

  const guardrails = context.guardrails
    .slice(0, MAX_GUARDRAIL_LINES)
    .map((g) => (forMod ? description(g) : g))
    .filter((g) => !forMod || g !== '');
  if (guardrails.length > 0) {
    lines.push('Active guardrails:');
    for (const g of guardrails) lines.push(`  - ${g}`);
  }

  return lines.join('\n');
}
